INSERT INTO users(id,name,weight_kg) VALUES ('11111111-1111-4111-8111-111111111111','Алексей',86.4);
INSERT INTO exercises(name,slug,category,equipment,calorie_class,default_rest_seconds,primary_muscles,secondary_muscles,description,instructions,common_mistakes) VALUES
('Жим штанги лёжа','barbell-bench-press','грудь','Штанга','compound',150,'["Грудные мышцы"]'::jsonb,'["Трицепс","Передняя дельта"]'::jsonb,'Базовый горизонтальный жим для развития силы верхней части тела.','["Лягте на скамью, поставьте стопы на пол и сведите лопатки.","Возьмитесь за гриф чуть шире плеч и снимите штангу со стоек.","Плавно опустите гриф к нижней части груди, удерживая предплечья вертикально.","Выжмите штангу вверх, сохраняя контакт таза со скамьёй."]'::jsonb,'["Отбив грифа от груди","Отрыв таза от скамьи","Слишком широко разведённые локти"]'::jsonb),
('Жим гантелей под углом','incline-dumbbell-press','грудь','Гантели','compound',120,'["Грудные мышцы"]'::jsonb,'["Передняя дельта","Трицепс"]'::jsonb,'Жим на наклонной скамье с независимым движением каждой руки.','["Установите наклон скамьи около 20–35 градусов.","Удерживайте гантели у верхней части груди, сведите лопатки.","Выжмите гантели вверх без удара друг о друга.","Медленно опустите их в комфортную нижнюю точку."]'::jsonb,'["Слишком крутой наклон","Сведение гантелей ударом","Потеря контроля в нижней точке"]'::jsonb),
('Сведение рук в кроссовере','cable-fly','грудь','Блок','isolation',75,'["Грудные мышцы"]'::jsonb,'["Передняя дельта"]'::jsonb,'Изолированное сведение рук с постоянным сопротивлением блока.','["Установите рукояти на уровне груди и сделайте шаг вперёд.","Слегка согните локти и зафиксируйте этот угол.","Сведите руки перед собой по дуге.","Разведите руки плавно, без чрезмерного растяжения."]'::jsonb,'["Разгибание локтей во время движения","Рывок корпусом"]'::jsonb),
('Тяга верхнего блока','lat-pulldown','спина','Тренажёр','machine_compound',120,'["Широчайшие"]'::jsonb,'["Бицепс","Ромбовидные"]'::jsonb,'Вертикальная тяга к груди с контролем лопаток.','["Зафиксируйте бёдра под валиком и возьмите рукоять.","Опустите плечи и направьте локти вниз.","Подтяните рукоять к верхней части груди.","Медленно верните руки вверх, сохраняя контроль."]'::jsonb,'["Тяга за голову","Раскачивание корпуса","Сильное отклонение назад"]'::jsonb),
('Тяга с упором грудью','chest-supported-row','спина','Гантели','compound',120,'["Ромбовидные","Широчайшие"]'::jsonb,'["Задняя дельта","Бицепс"]'::jsonb,'Горизонтальная тяга с опорой груди на наклонную скамью.','["Лягте грудью на наклонную скамью, стопы поставьте устойчиво.","Опустите руки с гантелями под плечами.","Подтяните гантели к рёбрам, сводя лопатки.","Опустите гантели плавно до выпрямления рук."]'::jsonb,'["Отрыв груди от скамьи","Подъём плеч к ушам"]'::jsonb),
('Тяга горизонтального блока','seated-cable-row','спина','Блок','machine_compound',120,'["Широчайшие","Ромбовидные"]'::jsonb,'["Бицепс","Задняя дельта"]'::jsonb,'Seated cable row — тяга сидя к поясу.','["Сядьте с немного согнутыми коленями и нейтральной спиной.","Удерживайте рукоять перед собой, опустите плечи.","Подтяните рукоять к животу, ведя локти назад.","Верните рукоять, не округляя поясницу."]'::jsonb,'["Раскачивание корпусом","Чрезмерный прогиб в пояснице"]'::jsonb),
('Жим гантелей сидя','seated-dumbbell-press','плечи','Гантели','compound',120,'["Дельтовидные"]'::jsonb,'["Трицепс","Верх груди"]'::jsonb,'Вертикальный жим с опорой спины.','["Сядьте на скамью с опорой спины, стопы прижмите к полу.","Поднимите гантели до уровня ушей.","Выжмите гантели вверх, не выгибая поясницу.","Опустите гантели контролируемо до исходного положения."]'::jsonb,'["Избыточный прогиб поясницы","Удар гантелями наверху"]'::jsonb),
('Подъём гантелей в стороны','lateral-raise','плечи','Гантели','isolation',75,'["Средняя дельта"]'::jsonb,'["Надостная мышца"]'::jsonb,'Отведение рук в стороны с умеренным весом.','["Встаньте устойчиво, держите гантели у бёдер.","Немного согните локти и поднимите руки в стороны.","Остановитесь около уровня плеч.","Медленно опустите гантели без раскачивания."]'::jsonb,'["Рывок ногами","Подъём плеч к ушам"]'::jsonb),
('Обратная бабочка','reverse-pec-deck','плечи','Тренажёр','isolation',75,'["Задняя дельта"]'::jsonb,'["Ромбовидные","Трапеция"]'::jsonb,'Разведение рук назад в тренажёре.','["Настройте сиденье так, чтобы рукояти были на уровне плеч.","Прижмите грудь к опоре и немного согните локти.","Разведите руки назад без рывка.","Верните рукояти медленно, удерживая грудь на опоре."]'::jsonb,'["Слишком большой вес","Переразгибание поясницы"]'::jsonb),
('Сгибание рук с гантелями','dumbbell-curl','бицепс','Гантели','isolation',75,'["Бицепс"]'::jsonb,'["Плечевая мышца","Предплечья"]'::jsonb,'Сгибание локтя с разворотом ладоней вверх.','["Встаньте устойчиво, расположите локти рядом с корпусом.","Поднимайте гантели, разворачивая ладони вверх.","Сократите бицепс без движения плечом вперёд.","Медленно разогните руки."]'::jsonb,'["Раскачивание корпуса","Выведение локтей вперёд"]'::jsonb),
('Молотковые сгибания','hammer-curl','бицепс','Гантели','isolation',75,'["Плечевая мышца","Бицепс"]'::jsonb,'["Плечелучевая мышца"]'::jsonb,'Hammer curl — сгибания с нейтральным хватом.','["Возьмите гантели ладонями друг к другу.","Зафиксируйте локти возле корпуса.","Согните руки, не меняя положение кистей.","Опустите гантели медленно."]'::jsonb,'["Залом кисти","Помощь корпусом"]'::jsonb),
('Разгибание рук на блоке','triceps-pushdown','трицепс','Блок','isolation',75,'["Трицепс"]'::jsonb,'["Предплечья"]'::jsonb,'Разгибание локтей с верхнего блока.','["Встаньте перед блоком и возьмитесь за рукоять.","Прижмите локти к бокам, держите плечи неподвижно.","Разогните руки вниз без резкого замыкания локтя.","Верните рукоять до комфортного сгибания."]'::jsonb,'["Движение плечами","Наклон всем весом на рукоять"]'::jsonb),
('Разгибание рук над головой','overhead-triceps-extension','трицепс','Блок','isolation',90,'["Трицепс"]'::jsonb,'["Мышцы корпуса"]'::jsonb,'Разгибание рук с канатом над головой.','["Повернитесь спиной к блоку и удерживайте канат над головой.","Сделайте устойчивый шаг вперёд и напрягите корпус.","Разогните локти, сохраняя плечи на месте.","Плавно верните канат за голову."]'::jsonb,'["Разведение локтей слишком широко","Прогиб в пояснице"]'::jsonb),
('Жим ногами','leg-press','квадрицепс','Тренажёр','machine_compound',150,'["Квадрицепс","Ягодичные"]'::jsonb,'["Приводящие мышцы"]'::jsonb,'Многосуставное разгибание ног в тренажёре.','["Прижмите спину и таз к опоре, стопы поставьте на платформу.","Снимите упоры и опустите платформу до комфортной глубины.","Следите, чтобы колени двигались в направлении носков.","Выжмите платформу, не замыкая колени рывком."]'::jsonb,'["Отрыв таза от опоры","Сведение коленей внутрь"]'::jsonb),
('Разгибание ног','leg-extension','квадрицепс','Тренажёр','isolation',75,'["Квадрицепс"]'::jsonb,'["Мышцы голени"]'::jsonb,'Изолированное разгибание коленей сидя.','["Совместите ось тренажёра с коленями.","Расположите валик над передней частью голеностопа.","Разогните ноги плавным движением.","Медленно опустите валик, не бросая вес."]'::jsonb,'["Рывок в начале","Отрыв таза от сиденья"]'::jsonb),
('Приседания с гантелью','goblet-squat','квадрицепс','Гантель','compound',120,'["Квадрицепс","Ягодичные"]'::jsonb,'["Мышцы корпуса","Приводящие мышцы"]'::jsonb,'Приседание с гантелью перед грудью.','["Держите гантель перед грудью, стопы поставьте устойчиво.","Согните колени и тазобедренные суставы, опуская таз.","Сохраняйте колени по направлению носков и опору всей стопой.","Встаньте без рывка, удерживая корпус стабильным."]'::jsonb,'["Отрыв пяток","Сведение коленей"]'::jsonb),
('Сгибание ног','leg-curl','бицепс бедра','Тренажёр','isolation',90,'["Задняя поверхность бедра"]'::jsonb,'["Икроножные"]'::jsonb,'Сгибание коленей в тренажёре.','["Отрегулируйте тренажёр под длину ног.","Расположите валик над пятками и зафиксируйте таз.","Согните колени до комфортного положения.","Разогните ноги медленно, сохраняя напряжение."]'::jsonb,'["Подъём таза","Резкое возвращение веса"]'::jsonb),
('Румынская тяга','romanian-deadlift','бицепс бедра','Штанга','compound',150,'["Задняя поверхность бедра","Ягодичные"]'::jsonb,'["Разгибатели спины","Предплечья"]'::jsonb,'Наклон с отведением таза и небольшим сгибанием коленей.','["Держите штангу у бёдер, колени немного согните.","Отведите таз назад, ведя гриф близко к ногам.","Опускайтесь до комфортного натяжения задней поверхности бедра.","Разогните тазобедренные суставы, сохраняя нейтральную спину."]'::jsonb,'["Округление поясницы","Отведение грифа от ног"]'::jsonb),
('Ягодичный мост со штангой','hip-thrust','ягодицы','Штанга','compound',120,'["Ягодичные"]'::jsonb,'["Задняя поверхность бедра","Мышцы корпуса"]'::jsonb,'Hip thrust — разгибание таза с опорой на скамью.','["Расположите верх спины на устойчивой скамье и защитную накладку на тазу.","Поставьте стопы так, чтобы голени наверху были близки к вертикали.","Поднимите таз, сокращая ягодицы.","Опустите таз под контролем, не переразгибая поясницу."]'::jsonb,'["Чрезмерный прогиб наверху","Неустойчивая скамья"]'::jsonb),
('Зашагивания на платформу','step-up','ягодицы','Гантели','high_intensity',120,'["Ягодичные","Квадрицепс"]'::jsonb,'["Задняя поверхность бедра","Мышцы корпуса"]'::jsonb,'Step-up — подъём на устойчивую платформу.','["Поставьте одну стопу целиком на платформу подходящей высоты.","Перенесите вес на переднюю ногу.","Поднимитесь усилием этой ноги, удерживая таз ровно.","Медленно опуститесь и выполните повторы другой ногой."]'::jsonb,'["Отталкивание нижней ногой","Потеря равновесия на высокой платформе"]'::jsonb),
('Подъёмы на носки стоя','standing-calf-raise','икры','Тренажёр','isolation',60,'["Икроножные"]'::jsonb,'["Камбаловидная мышца"]'::jsonb,'Calf raises — подошвенное сгибание стопы стоя.','["Расположите переднюю часть стоп на платформе.","Удерживайте колени мягкими и корпус стабильным.","Поднимитесь на носки и сделайте короткую паузу.","Медленно опустите пятки до комфортной амплитуды."]'::jsonb,'["Пружинящие движения","Завал стоп наружу"]'::jsonb),
('Подъёмы на носки сидя','seated-calf-raise','икры','Тренажёр','isolation',60,'["Камбаловидная мышца"]'::jsonb,'["Икроножные"]'::jsonb,'Подъём пяток с согнутыми коленями.','["Сядьте и расположите валики над коленями.","Поставьте переднюю часть стоп на платформу.","Поднимите пятки плавно, сохраняя опору носками.","Опустите пятки под контролем."]'::jsonb,'["Подбрасывание веса","Слишком короткая амплитуда"]'::jsonb),
('Скручивания на блоке','cable-crunch','core','Блок','isolation',60,'["Прямая мышца живота"]'::jsonb,'["Косые мышцы"]'::jsonb,'Сгибание корпуса с сопротивлением верхнего блока.','["Встаньте на колени перед блоком и удерживайте канат у головы.","Стабилизируйте таз и немного округлите верх спины.","Приблизьте рёбра к тазу за счёт мышц живота.","Вернитесь плавно, не вытягивая канат руками."]'::jsonb,'["Тяга руками","Сгибание только в тазобедренном суставе"]'::jsonb),
('Обратные скручивания','reverse-crunch','core','Коврик','isolation',60,'["Прямая мышца живота"]'::jsonb,'["Косые мышцы"]'::jsonb,'Подкручивание таза лёжа на спине.','["Лягте на спину, согните колени и прижмите руки к полу.","Подтяните колени к корпусу, слегка приподнимая таз.","Избегайте маха ногами и резких движений.","Медленно верните таз на коврик."]'::jsonb,'["Раскачивание ногами","Сильный прогиб поясницы"]'::jsonb);
INSERT INTO exercise_media(exercise_id,type,url,position) SELECT id,'image','/illustrations/' || CASE WHEN category IN ('грудь','трицепс') THEN 'push' WHEN category IN ('спина','бицепс','плечи') THEN 'pull' ELSE 'legs' END || '.svg',0 FROM exercises;
