


-- Explicit demo history; all statistics are computed from these completed sets.
DO $$
DECLARE i int; j int; sid uuid; seid uuid; tid uuid; ex record; n text; at timestamptz; w numeric; kcal numeric;
BEGIN
 FOR i IN 1..9 LOOP
  tid := ('22222222-2222-4222-8222-22222222222' || ((i-1)%3+1))::uuid;
  SELECT name INTO n FROM workout_templates WHERE id=tid;
  at := date_trunc('day',now()) - ((29-i*3) || ' days')::interval + interval '17 hours';
   VALUES ('11111111-1111-4111-8111-111111111111',tid,n,at,at+interval '62 minutes',86.4,'Демонстрационная тренировка') RETURNING id INTO sid;
  FOR ex IN SELECT te.*,e.category,e.calorie_class FROM workout_template_exercises te JOIN exercises e ON e.id=te.exercise_id WHERE te.template_id=tid ORDER BY te.position LOOP
    VALUES(sid,ex.exercise_id,ex.position,ex.target_reps_min,ex.target_reps_max,ex.rest_seconds,at+ex.position*interval '10 minutes',at+(ex.position+1)*interval '10 minutes') RETURNING id INTO seid;
   w := CASE WHEN ex.category='квадрицепс' AND ex.position=0 THEN 100 WHEN ex.category='core' THEN 20 WHEN ex.category IN ('бицепс','плечи') THEN 12.5 WHEN ex.calorie_class='isolation' THEN 25 WHEN ex.category='грудь' AND ex.position=0 THEN 65 ELSE 40 END + floor((i-1)/3)*2.5;
   FOR j IN 1..3 LOOP
    VALUES(seid,j,w,12-j,2,8,true,at+(ex.position*600+j*150)*interval '1 second',at+(ex.position*600+j*150+40)*interval '1 second');
   END LOOP;
  END LOOP;
  SELECT (sum(40 * CASE e.calorie_class WHEN 'isolation' THEN 4 WHEN 'machine_compound' THEN 4.5 WHEN 'compound' THEN 5.5 ELSE 6 END * 1.1) + (3720-count(*)*40)*1.8)/60*3.5*86.4/200 INTO kcal
   FROM workout_sets ws JOIN workout_session_exercises se ON se.id=ws.session_exercise_id JOIN exercises e ON e.id=se.exercise_id WHERE se.session_id=sid;
  UPDATE workout_sessions SET estimated_calories=kcal WHERE id=sid;
 END LOOP;
 FOR i IN 0..7 LOOP
 END LOOP;
END $$;
